int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;
    vector<string> g(N, string(M, '0'));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            char c; cin >> c; 
            g[i][j] = c;
        }
    }

    const int MAXV = 1000000; 
    vector<char> is_prime(MAXV, 1);
    is_prime[0] = is_prime[1] = 0;
    for (int p = 2; p * p < MAXV; ++p) {
        if (is_prime[p]) {
            for (int q = p*p; q < MAXV; q += p) is_prime[q] = 0;
        }
    }

    long long count = 0;
    long long total = 0;

    const int dx[3] = {0, 1, 1};
    const int dy[3] = {1, 0, 1};

    for (int dir = 0; dir < 3; ++dir) {
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < M; ++j) {
                char start = g[i][j];
                if (start == '0') continue; 
                int x = i, y = j;
                int num = 0;
                for (int len = 1; len <= 6; ++len) {
                    if (x < 0 || x >= N || y < 0 || y >= M) break;
                    num = num * 10 + (g[x][y] - '0');
                    if (num < MAXV && is_prime[num] and !(len == 1 and dir != 0)) {
                        ++count;
                        total += num;
                    }
                    x += dx[dir];
                    y += dy[dir];

                }
            }
        }
    }

    cout << count << " " << total << "\n";
}